const GRASS = 1;

const getPositionString = (row, col) => `${row}, ${col}`;
const directions = [
    [0, 1],
    [1, 0],
    [0, -1],
    [-1, 0],
];

const isInBounds = (grid, row, col) => {
    const numRows = grid.length;
    const numCols = grid[0].length;

    const rowInBounds = row >= 0 && row < numRows;
    const colInBounds = col >= 0 && col < numCols;

    return rowInBounds && colInBounds;
};

// CONTRACT for getCampsiteSize(park, row, col, visited):
//     when this call returns, every grass square connected to
//     (`row`, `col`) is in the visited set, and the returned value is
//     how many squares this call put there. If (`row`, `col`) is not
//     a fresh grass square, it returns 0 and nothing new goes in.
const getCampsiteSize = (park, row, col, visited) => {
    // Base cases
    if (!isInBounds(park, row, col)) return 0;

    const curPositionString = getPositionString(row, col);
    if (visited.has(curPositionString)) return 0;

    if (park[row][col] !== GRASS) return 0;

    // Process node
    visited.add(curPositionString);

    // This square contributes 1 to the campsite, plus every connected
    // grass square we discover from here.
    let campsiteSize = 1;

    // Recurse on potential neighbors
    for (const direction of directions) {
        const [rowChange, colChange] = direction;

        const newRow = row + rowChange;
        const newCol = col + colChange;

        // The recursive leap of faith, one level down: this call has
        // the SAME contract — when it returns, every grass square
        // connected to the neighboring square is in visited, and it hands
        // back how many it added. Trust it, do not trace it. The 1 for
        // this square + each direction's guaranteed count = exactly this
        // function's contract.
        campsiteSize += getCampsiteSize(park, newRow, newCol, visited);
    }

    return campsiteSize;
};

const countPerfectCampsites = (park, k) => {
    const numRows = park.length;
    const numCols = park[0].length;

    let numPerfectCampsites = 0;
    const visited = new Set();

    for (let row = 0; row < numRows; row++) {
        for (let col = 0; col < numCols; col++) {
            const curPositionString = getPositionString(row, col);

            if (visited.has(curPositionString)) continue;

            const terrainType = park[row][col];
            if (terrainType !== GRASS) continue;

            // One DFS measures this entire campsite, so we can compare
            // its full size against k before moving on.
            // The recursive leap of faith: trust the contract. When this
            // call returns, this whole campsite is in visited — the loop can
            // never count it again — and `campsiteSize` is its exact number
            // of squares. We do not trace inside; we just compare it to k.
            const campsiteSize = getCampsiteSize(park, row, col, visited);

            if (campsiteSize === k) numPerfectCampsites++;
        }
    }

    return numPerfectCampsites;
};

const buildGraph = (edges) => {
    const graph = {};

    for (const edge of edges) {
        const [nodeOne, nodeTwo] = edge;

        const nodeOneInGraph = graph.hasOwnProperty(nodeOne);
        const nodeTwoInGraph = graph.hasOwnProperty(nodeTwo);

        if (!nodeOneInGraph) graph[nodeOne] = [];
        if (!nodeTwoInGraph) graph[nodeTwo] = [];

        graph[nodeOne].push(nodeTwo);
        graph[nodeTwo].push(nodeOne);
    }

    return graph;
};

// CONTRACT for spreadRumor(graph, employee, visited):
//     when this call returns, `employee` and every employee reachable
//     from them through chains of friendships is in the visited set.
const spreadRumor = (graph, employee, visited) => {
    // Base cases
    if (visited.has(employee)) return;

    // Process node
    visited.add(employee);

    // Recurse on neighbors
    const employeeInGraph = graph.hasOwnProperty(employee);
    if (!employeeInGraph) return;

    const friends = graph[employee];

    for (const friend of friends) {
        // The recursive leap of faith, one level down: this call has
        // the SAME contract — when it returns, `friend` and everyone
        // reachable from them is in the visited set. Trust it, do not
        // trace it. This function already put `employee` into visited,
        // and each friend's contract covers everyone reachable beyond
        // them — together, that is this function's full contract, kept.
        spreadRumor(graph, friend, visited);
    }
};

const countWhoHear = (n, friendships, start) => {
    const graph = buildGraph(friendships);

    // Everyone the DFS reaches hears the rumor, so the visited set ends
    // up holding exactly the employees in start's chain of friends.
    const visited = new Set();

    // The recursive leap of faith: trust the contract. When this
    // call returns, `start` and everyone reachable from them is in
    // the visited set. We do not trace inside; we just return the
    // size of the set.
    spreadRumor(graph, start, visited);

    return visited.size;
};

const TOP_LEVEL_DEPTH = 1;

// CONTRACT for countItemsAtEachDepth(items, depth, itemCountsByDepth):
//     when this call returns, every item inside `items` — however
//     deeply nested — has been counted in `itemCountsByDepth` under
//     its own depth, where the elements directly inside sit at depth
//     `depth`.
const countItemsAtEachDepth = (items, depth, itemCountsByDepth) => {
    // Base case: an empty container is handled automatically
    // (the loop below never runs, so the recursion stops).

    for (const element of items) {
        const elementIsItem = !Array.isArray(element);

        // Process node
        if (elementIsItem) {
            const depthHasCount = itemCountsByDepth.hasOwnProperty(depth);
            if (!depthHasCount) itemCountsByDepth[depth] = 0;

            itemCountsByDepth[depth]++;
            continue;
        }

        // Recurse on neighbors
        // Opening a container pushes everything inside one level deeper.
        // The recursive leap of faith, one level down: this call has
        // the SAME contract — when it returns, every item inside this
        // container has been counted under its correct depth. Trust it,
        // do not trace it. Items counted directly here + each container's
        // guaranteed counts = exactly this function's contract.
        countItemsAtEachDepth(element, depth + 1, itemCountsByDepth);
    }
};

const busiestDepth = (items) => {
    const itemCountsByDepth = {};

    // The recursive leap of faith: trust the contract. When this
    // call returns, `itemCountsByDepth` holds a complete tally: how
    // many items sit at every depth of the shelf. We do not trace
    // inside; we just scan the tally for the busiest depth.
    countItemsAtEachDepth(items, TOP_LEVEL_DEPTH, itemCountsByDepth);

    const allDepths = Object.keys(itemCountsByDepth)
        .map(Number)
        .sort((depthA, depthB) => depthA - depthB);

    let busiestDepthSoFar = 0;
    let mostItemsSoFar = 0;

    // Scanning depths from shallowest to deepest means a strict '>'
    // comparison automatically breaks ties in favor of the smaller depth.
    for (const depth of allDepths) {
        const itemsAtDepth = itemCountsByDepth[depth];

        if (itemsAtDepth > mostItemsSoFar) {
            mostItemsSoFar = itemsAtDepth;
            busiestDepthSoFar = depth;
        }
    }

    return busiestDepthSoFar;
};

const START_ROOM = 0;

// CONTRACT for collectGold(rooms, gold, room, visited):
//     when this call returns, `room` and every room reachable through
//     keys from it is in the visited set, and the returned value is
//     the total gold from the rooms this call put into visited.
const collectGold = (rooms, gold, room, visited) => {
    // Base cases
    if (visited.has(room)) return 0;

    // Process node
    // The visited set guarantees each room's gold is taken exactly once,
    // even if several rooms hold a key to it.
    visited.add(room);

    let goldCollected = gold[room];

    // Recurse on neighbors
    const keysInRoom = rooms[room];

    for (const key of keysInRoom) {
        // The recursive leap of faith, one level down: this call has
        // the SAME contract — when it returns, room `key` and everything
        // reachable from it is in visited, and it hands back the gold it
        // collected there. Trust it, do not trace it. This room's own
        // gold + each key call's guaranteed haul = exactly this
        // function's contract.
        goldCollected += collectGold(rooms, gold, key, visited);
    }

    return goldCollected;
};

const totalGoldCollected = (rooms, gold) => {
    const visited = new Set();

    // The recursive leap of faith: trust the contract. When this
    // call returns, its value is all the gold reachable from room 0.
    // We do not trace inside; we just return that total.
    return collectGold(rooms, gold, START_ROOM, visited);
};

const buildGraph = (edges) => {
    const graph = {};

    for (const edge of edges) {
        const [nodeOne, nodeTwo] = edge;

        const nodeOneInGraph = graph.hasOwnProperty(nodeOne);
        const nodeTwoInGraph = graph.hasOwnProperty(nodeTwo);

        if (!nodeOneInGraph) graph[nodeOne] = [];
        if (!nodeTwoInGraph) graph[nodeTwo] = [];

        graph[nodeOne].push(nodeTwo);
        graph[nodeTwo].push(nodeOne);
    }

    return graph;
};

// CONTRACT for canReachTarget(graph, campsite, target, floodedSet, visited):
//     when this call returns, it returns true if the search can walk
//     from `campsite` to `target` without stepping into a flooded
//     campsite, and false otherwise. Every campsite it explores goes
//     into the visited set, so none is explored twice.
const canReachTarget = (graph, campsite, target, floodedSet, visited) => {
    // Base cases
    if (campsite === target) return true;

    if (visited.has(campsite)) return false;

    // Process node
    visited.add(campsite);

    // Recurse on neighbors
    const campsiteInGraph = graph.hasOwnProperty(campsite);
    if (!campsiteInGraph) return false;

    const neighbors = graph[campsite];

    for (const neighbor of neighbors) {
        // A flooded campsite is off-limits even as a pass-through,
        // so the DFS refuses to step into it at all.
        if (floodedSet.has(neighbor)) continue;

        // The recursive leap of faith, one level down: this call has
        // the SAME contract — when it returns, it tells us whether
        // `target` can be reached from `neighbor` on dry trails. Trust
        // it, do not trace it. If any neighbor's answer is true, a route
        // through that neighbor exists, so returning true keeps this
        // function's contract; if every answer is false, returning false
        // keeps it too.
        const foundTarget = canReachTarget(
            graph,
            neighbor,
            target,
            floodedSet,
            visited,
        );

        if (foundTarget) return true;
    }

    return false;
};

const canReachFinish = (n, trails, flooded, start, finish) => {
    const floodedSet = new Set(flooded);

    // A hike cannot begin or end underwater.
    if (floodedSet.has(start)) return false;
    if (floodedSet.has(finish)) return false;

    const graph = buildGraph(trails);
    const visited = new Set();

    // The recursive leap of faith: trust the contract. When this
    // call returns, its value tells us whether `finish` can be
    // reached from `start` while avoiding every flooded campsite. We
    // do not trace inside; we just return the answer.
    return canReachTarget(graph, start, finish, floodedSet, visited);
};
